import{_ as a,o as e,c as n,a as i}from"./app.DkoUFz-u.js";const h=JSON.parse('{"title":"OAuth 2.0 PKCE 扩展","description":"","frontmatter":{},"headers":[],"relativePath":"backend/auth/oauth/pkce.md","filePath":"backend/auth/oauth/pkce.md"}'),c={name:"backend/auth/oauth/pkce.md"};function l(o,s,p,t,_,r){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="oauth-2-0-pkce-扩展" tabindex="-1">OAuth 2.0 PKCE 扩展 <a class="header-anchor" href="#oauth-2-0-pkce-扩展" aria-label="Permalink to &quot;OAuth 2.0 PKCE 扩展&quot;">​</a></h1><blockquote><p>这份学习笔记将帮你系统掌握OAuth PKCE扩展。PKCE，全称<strong>Proof Key for Code Exchange</strong>，是OAuth 2.0授权码流程的一个安全扩展，最初旨在保护移动和单页应用等公共客户端。</p></blockquote><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[客户端准备授权请求] --&gt; B[生成 code_verifier]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C[派生 code_challenge]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D[发送授权请求&lt;br&gt;含 code_challenge]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; E[用户认证与授权]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; F[授权服务器返回授权码]</span></span>
<span class="line"><span class="__shiki_140thh">    F --&gt; G[使用授权码+code_verifier&lt;br&gt;请求令牌]</span></span>
<span class="line"><span class="__shiki_140thh">    G --&gt; H[授权服务器验证&lt;br&gt;code_verifier 与 challenge 匹配]</span></span>
<span class="line"><span class="__shiki_140thh">    H --&gt; I[返回访问令牌]</span></span></code></pre></div><h2 id="🔑-一、pkce的核心组件" tabindex="-1">🔑 一、PKCE的核心组件 <a class="header-anchor" href="#🔑-一、pkce的核心组件" aria-label="Permalink to &quot;🔑 一、PKCE的核心组件&quot;">​</a></h2><p>PKCE通过三个关键参数来确保安全，理解它们至关重要：</p><ul><li><strong>Code Verifier</strong>：一个由客户端生成的高熵随机字符串，长度在43至128字符之间。它是整个流程的“秘密”，必须在本地安全存储。</li><li><strong>Code Challenge</strong>：由<code>code_verifier</code>通过特定方法（如下述<code>code_challenge_method</code>）派生而来。此挑战值在初始授权请求中发送给授权服务器。</li><li><strong>Code Challenge Method</strong>：指定如何从<code>code_verifier</code>生成<code>code_challenge</code>。主要有两种方法： <ul><li><strong><code>S256</code></strong>：<strong>推荐方法</strong>。使用SHA-256算法对<code>code_verifier</code>进行哈希，再进行Base64URL编码。因其安全性更高而被推荐。</li><li><strong><code>plain</code></strong>：直接使用原始的<code>code_verifier</code>作为<code>code_challenge</code>。安全性较低，仅在客户端不支持<code>S256</code>时考虑使用。</li></ul></li></ul><h2 id="🛡️-二、pkce-为何重要" tabindex="-1">🛡️ 二、PKCE 为何重要 <a class="header-anchor" href="#🛡️-二、pkce-为何重要" aria-label="Permalink to &quot;🛡️ 二、PKCE 为何重要&quot;">​</a></h2><p>PKCE主要解决了授权码在传输过程中可能被拦截的风险。在一些场景下（如移动设备上），恶意应用可能通过注册相同的重定向URI来截获授权码。PKCE通过<strong>绑定初始请求与令牌请求</strong>来防御此类攻击：拦截者即便拿到了授权码，由于没有原始的<code>code_verifier</code>，也无法向授权服务器兑换到访问令牌。</p><p>鉴于其重要性，<strong>从OAuth 2.1开始，PKCE已强制用于所有类型的OAuth客户端</strong>，包括公共客户端和机密客户端。</p><h2 id="⚙️-三、pkce-流程详解" tabindex="-1">⚙️ 三、PKCE 流程详解 <a class="header-anchor" href="#⚙️-三、pkce-流程详解" aria-label="Permalink to &quot;⚙️ 三、PKCE 流程详解&quot;">​</a></h2><p>结合上面的流程图，我们来分解PKCE授权码流程的每一步：</p><ol><li><p><strong>准备授权请求</strong></p><ul><li>客户端首先生成一个高熵的加密随机字符串作为 <strong><code>code_verifier</code></strong> 。</li><li>客户端使用选定的 <strong><code>code_challenge_method</code></strong>（推荐S256）从<code>code_verifier</code>派生出 <strong><code>code_challenge</code></strong> 。</li><li>客户端将用户重定向至授权服务器的<code>/authorize</code>端点，请求中除了常规的<code>client_id</code>、<code>response_type=code</code>、<code>redirect_uri</code>等参数，还必须包含 <strong><code>code_challenge</code></strong> 和 <strong><code>code_challenge_method</code></strong> 。</li></ul></li><li><p><strong>用户认证与授权</strong></p><ul><li>用户在授权服务器上进行身份验证并批准客户端请求的权限范围。</li></ul></li><li><p><strong>颁发授权码</strong></p><ul><li>认证授权成功后，授权服务器将用户重定向回客户端指定的<code>redirect_uri</code>，并在URL中附上 <strong>授权码（code）</strong> 。授权服务器会记录之前收到的<code>code_challenge</code>和<code>code_challenge_method</code>。</li></ul></li><li><p><strong>兑换访问令牌</strong></p><ul><li>客户端使用上一步获取的授权码，向授权服务器的<code>/token</code>端点发起POST请求，请求体中需包含 <strong><code>code_verifier</code></strong>（即最初生成的秘密随机字符串）。</li><li>授权服务器收到请求后，会使用之前记录的<code>code_challenge_method</code>对请求中的<code>code_verifier</code>进行相同的变换，并将计算结果与最初授权请求中的<code>code_challenge</code>进行比对验证。</li></ul></li><li><p><strong>颁发令牌</strong></p><ul><li>验证通过（授权码有效、<code>code_verifier</code>与<code>code_challenge</code>匹配、重定向URI一致等）后，授权服务器会返回访问令牌（Access Token），通常也会包含刷新令牌（Refresh Token）。</li></ul></li></ol><h2 id="💻-四、代码示例" tabindex="-1">💻 四、代码示例 <a class="header-anchor" href="#💻-四、代码示例" aria-label="Permalink to &quot;💻 四、代码示例&quot;">​</a></h2><p>以下JavaScript代码示例展示了<code>code_verifier</code>和<code>code_challenge</code>的生成方法（请注意，实际应用中应使用经过严格安全审查的库）：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// 生成 code_verifier</span></span>
<span class="line"><span class="__shiki_1itgoe">import</span><span class="__shiki_140thh"> { fromUint8Array } </span><span class="__shiki_1itgoe">from</span><span class="__shiki_mdbnqw"> &#39;js-base64&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> codeVerifier</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_1t8gfj"> fromUint8Array</span><span class="__shiki_140thh">(crypto.</span><span class="__shiki_1t8gfj">getRandomValues</span><span class="__shiki_140thh">(</span><span class="__shiki_1itgoe">new</span><span class="__shiki_1t8gfj"> Uint8Array</span><span class="__shiki_140thh">(</span><span class="__shiki_dzsirb">64</span><span class="__shiki_140thh">)), </span><span class="__shiki_dzsirb">true</span><span class="__shiki_140thh">);</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">// 生成 code_challenge (使用S256方法)</span></span>
<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> encodedCodeVerifier</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_1itgoe"> new</span><span class="__shiki_1t8gfj"> TextEncoder</span><span class="__shiki_140thh">().</span><span class="__shiki_1t8gfj">encode</span><span class="__shiki_140thh">(codeVerifier);</span></span>
<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> codeChallengeBuffer</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_1itgoe"> await</span><span class="__shiki_140thh"> crypto.subtle.</span><span class="__shiki_1t8gfj">digest</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&#39;SHA-256&#39;</span><span class="__shiki_140thh">, encodedCodeVerifier);</span></span>
<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> codeChallenge</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_1t8gfj"> fromUint8Array</span><span class="__shiki_140thh">(</span><span class="__shiki_1itgoe">new</span><span class="__shiki_1t8gfj"> Uint8Array</span><span class="__shiki_140thh">(codeChallengeBuffer), </span><span class="__shiki_dzsirb">true</span><span class="__shiki_140thh">);</span></span></code></pre></div><p>授权请求示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">GET /authorize?</span></span>
<span class="line"><span class="__shiki_wvjl67">  response_type=code</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;client_id=YOUR_CLIENT_ID</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;redirect_uri=https%3A%2F%2Fclient.example.com%2Fcallback</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;scope=openid%20profile</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;code_challenge=YOUR_CODE_CHALLENGE</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;code_challenge_method=S256</span></span>
<span class="line"><span class="__shiki_wvjl67">  &amp;state=abc123 HTTP/1.1</span></span></code></pre></div><p>令牌请求示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">POST /token HTTP/1.1</span></span>
<span class="line"><span class="__shiki_wvjl67">Host: your-authorization-server.com</span></span>
<span class="line"><span class="__shiki_wvjl67">Content-Type: application/x-www-form-urlencoded</span></span>
<span class="line"><span class="__shiki_wvjl67"></span></span>
<span class="line"><span class="__shiki_wvjl67">grant_type=authorization_code</span></span>
<span class="line"><span class="__shiki_wvjl67">&amp;code=YOUR_AUTHORIZATION_CODE</span></span>
<span class="line"><span class="__shiki_wvjl67">&amp;redirect_uri=https%3A%2F%2Fclient.example.com%2Fcallback</span></span>
<span class="line"><span class="__shiki_wvjl67">&amp;client_id=YOUR_CLIENT_ID</span></span>
<span class="line"><span class="__shiki_wvjl67">&amp;code_verifier=YOUR_CODE_VERIFIER</span></span></code></pre></div><h2 id="🔐-五、pkce-与客户端密钥" tabindex="-1">🔐 五、PKCE 与客户端密钥 <a class="header-anchor" href="#🔐-五、pkce-与客户端密钥" aria-label="Permalink to &quot;🔐 五、PKCE 与客户端密钥&quot;">​</a></h2><p>关于PKCE流程中是否使用<code>client_secret</code>，需要注意以下几点：</p><ul><li><strong>公共客户端</strong>：对于无法安全存储机密（如移动App、单页应用）的公共客户端，<strong>PKCE允许在不使用<code>client_secret</code>的情况下进行令牌请求</strong>。这也是PKCE的一个重要价值。</li><li><strong>机密客户端</strong>：对于有后端的Web应用等机密客户端，<strong>即使使用了PKCE，通常仍建议同时使用<code>client_secret</code></strong>。这提供了双重保障：PKCE保护授权码交换，<code>client_secret</code>则验证客户端身份本身。</li><li><strong>策略差异</strong>：请注意，不同的授权服务器可能有不同策略。有些可能强制要求机密客户端使用<code>client_secret</code>，而有些平台（如某些搜索结果中提到的DigitalOcean）的授权码流程可能目前仍要求<code>client_secret</code>。<strong>务必查阅你所集成授权服务器的具体文档</strong>。</li></ul><h2 id="💎-六、核心要点总结" tabindex="-1">💎 六、核心要点总结 <a class="header-anchor" href="#💎-六、核心要点总结" aria-label="Permalink to &quot;💎 六、核心要点总结&quot;">​</a></h2><ul><li><strong>核心目标</strong>：PKCE通过防止授权码拦截攻击，增强了OAuth 2.0授权码流程的安全性。</li><li><strong>关键机制</strong>：利用<code>code_verifier</code>和<code>code_challenge</code>的绑定关系，确保兑换令牌的客户端就是发起授权请求的客户端。</li><li><strong>方法选择</strong>：优先使用 <strong><code>S256</code></strong> 方法生成<code>code_challenge</code>，避免使用不安全的<code>plain</code>方法。</li><li><strong>适用场景</strong>：<strong>所有类型的OAuth客户端都应使用PKCE</strong>，尤其在无法安全存储<code>client_secret</code>的<strong>公共客户端</strong>（如移动应用、单页应用）中至关重要。</li></ul><p>希望这份笔记能帮助你清晰地理解OAuth PKCE扩展。在实际集成时，务必参考你所使用的特定授权服务器的官方文档。</p>`,25)])])}const g=a(c,[["render",l]]);export{h as __pageData,g as default};
